attribute vec3 aO, aE; attribute float aT, aC; uniform float uTime; varying vec2 vP; varying float vC;
    void main(){ float u = uTime - aT; if (u < -.35 || u > 0.12){ gl_Position = vec4(2.,2.,2.,1.); return; }
      float k = clamp(u/0.12, 0., 1.), e = k*k*k; vec3 P = mix(aO, aE, e);
      vec4 mv = viewMatrix*vec4(P, 1.); float S = .07*(1. - .5*e); mv.xy += position.xy*S;
      vP = position.xy; vC = aC; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform vec3 uPoi, uPoiL, uBle, uBleL; varying vec2 vP; varying float vC;
    void main(){ float r = length(vP); vec3 c = mix(uPoi, uBle, vC), cl = mix(uPoiL, uBleL, vC);
      vec3 o = (c*exp(-r*r*5.) + mix(cl, vec3(1.), .5)*exp(-r*r*30.))*1.1*smoothstep(1., .8, r);
      if (max(o.r, max(o.g, o.b)) < .002) discard; gl_FragColor = vec4(o, 1.); }

